import { GoogleGenAI, Type, Modality } from "@google/genai";

const API_KEY = process.env.API_KEY || "";

export const chatWithMemoryBot = async (history: string[], userMessage: string) => {
  if (!API_KEY) return "Serviço de IA não configurado.";

  const ai = new GoogleGenAI({ apiKey: API_KEY });
  const model = "gemini-3-flash-preview";

  const systemInstruction = `
    Você é o 'Bot da Memória', o assistente do Museu Digital da Memória Viva da Caserna (PMRR).
    Seu tom é respeitoso, acolhedor e institucional, mas focado no lado humano da história.
    Você conhece a história da Guarda Territorial de Roraima e da PMRR.
    Ajude os usuários a encontrar histórias de veteranos e entender o legado da caserna.
    Sempre finalize com a assinatura: "Memória Viva - APP FESP".
  `;

  try {
    const response = await ai.models.generateContent({
      model,
      contents: [
        { role: 'user', parts: [{ text: `Histórico: ${history.join('\n')}\nUsuário: ${userMessage}` }] }
      ],
      config: {
        systemInstruction,
        temperature: 0.7,
      }
    });
    return response.text || "Desculpe, não consegui processar sua memória agora.";
  } catch (error) {
    console.error("Gemini Chat Error:", error);
    return "Erro ao conectar com a Memória Viva.";
  }
};

export const speakMemory = async (text: string): Promise<Uint8Array | null> => {
  if (!API_KEY) return null;
  const ai = new GoogleGenAI({ apiKey: API_KEY });

  try {
    const response = await ai.models.generateContent({
      model: "gemini-2.5-flash-preview-tts",
      contents: [{ parts: [{ text: `Leia com voz solene e respeitosa: ${text}` }] }],
      config: {
        responseModalities: [Modality.AUDIO],
        speechConfig: {
          voiceConfig: {
            prebuiltVoiceConfig: { voiceName: 'Kore' },
          },
        },
      },
    });

    const base64Audio = response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;
    if (base64Audio) {
      const binaryString = atob(base64Audio);
      const len = binaryString.length;
      const bytes = new Uint8Array(len);
      for (let i = 0; i < len; i++) {
        bytes[i] = binaryString.charCodeAt(i);
      }
      return bytes;
    }
  } catch (error) {
    console.error("Gemini TTS Error:", error);
  }
  return null;
};

import React, { useState, useEffect } from 'react';
import { Type, Moon, Sun, Plus, Minus, Eye } from 'lucide-react';

export const AccessibilityToolbar: React.FC = () => {
  const [highContrast, setHighContrast] = useState(false);
  const [fontSize, setFontSize] = useState(100);

  const toggleContrast = () => {
    setHighContrast(!highContrast);
    document.body.classList.toggle('high-contrast');
  };

  const adjustFont = (amount: number) => {
    const newSize = Math.min(Math.max(fontSize + amount, 80), 150);
    setFontSize(newSize);
    document.documentElement.style.fontSize = `${(newSize / 100) * 16}px`;
  };

  return (
    <div className="fixed bottom-6 right-6 flex flex-col gap-2 z-50">
      <div className="bg-white dark:bg-slate-800 p-2 rounded-full shadow-xl border border-slate-200 flex flex-col gap-2 group">
        <button 
          onClick={toggleContrast}
          className="p-3 bg-slate-100 hover:bg-slate-200 rounded-full transition-colors"
          title="Alternar Alto Contraste"
          aria-label="Alternar Alto Contraste"
        >
          {highContrast ? <Sun size={20} /> : <Moon size={20} />}
        </button>
        <button 
          onClick={() => adjustFont(10)}
          className="p-3 bg-slate-100 hover:bg-slate-200 rounded-full transition-colors"
          title="Aumentar Fonte"
          aria-label="Aumentar Fonte"
        >
          <Plus size={20} />
        </button>
        <button 
          onClick={() => adjustFont(-10)}
          className="p-3 bg-slate-100 hover:bg-slate-200 rounded-full transition-colors"
          title="Diminuir Fonte"
          aria-label="Diminuir Fonte"
        >
          <Minus size={20} />
        </button>
        <div className="p-3 bg-slate-900 text-white rounded-full flex items-center justify-center">
            <Eye size={20} />
        </div>
      </div>
    </div>
  );
};

import React, { useState, useRef, useEffect } from 'react';
import { MessageSquare, Send, X, Bot, User } from 'lucide-react';
import { chatWithMemoryBot } from '../services/geminiService';

export const MemoryBot: React.FC = () => {
  const [isOpen, setIsOpen] = useState(false);
  const [messages, setMessages] = useState<{role: 'bot' | 'user', text: string}[]>([
    { role: 'bot', text: 'Olá! Sou o Bot da Memória. O que você gostaria de saber sobre a nossa Caserna?' }
  ]);
  const [input, setInput] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const scrollRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [messages]);

  const handleSend = async () => {
    if (!input.trim() || isLoading) return;

    const userMsg = input.trim();
    setInput('');
    setMessages(prev => [...prev, { role: 'user', text: userMsg }]);
    setIsLoading(true);

    const history = messages.map(m => `${m.role}: ${m.text}`);
    const botResponse = await chatWithMemoryBot(history, userMsg);

    setMessages(prev => [...prev, { role: 'bot', text: botResponse }]);
    setIsLoading(false);
  };

  return (
    <div className="fixed bottom-6 left-6 z-50">
      {!isOpen && (
        <button 
          onClick={() => setIsOpen(true)}
          className="bg-indigo-900 text-white p-4 rounded-full shadow-2xl hover:bg-indigo-800 transition-all flex items-center gap-2"
          aria-label="Abrir Bot da Memória"
        >
          <Bot size={24} />
          <span className="font-semibold hidden md:inline">Bot da Memória</span>
        </button>
      )}

      {isOpen && (
        <div className="bg-white w-[350px] md:w-[400px] h-[500px] rounded-2xl shadow-2xl flex flex-col border border-indigo-100 overflow-hidden animate-in fade-in slide-in-from-bottom-4 duration-300">
          <div className="bg-indigo-900 p-4 text-white flex justify-between items-center">
            <div className="flex items-center gap-2">
              <Bot size={20} />
              <h3 className="font-bold">Memória Viva AI</h3>
            </div>
            <button onClick={() => setIsOpen(false)} className="hover:text-indigo-200">
              <X size={20} />
            </button>
          </div>

          <div ref={scrollRef} className="flex-1 overflow-y-auto p-4 space-y-4 bg-indigo-50/30">
            {messages.map((m, i) => (
              <div key={i} className={`flex ${m.role === 'user' ? 'justify-end' : 'justify-start'}`}>
                <div className={`max-w-[80%] p-3 rounded-2xl flex gap-2 ${
                  m.role === 'user' 
                    ? 'bg-indigo-600 text-white rounded-tr-none' 
                    : 'bg-white text-slate-800 shadow-sm rounded-tl-none border border-indigo-100'
                }`}>
                  <div className="mt-1">
                    {m.role === 'user' ? <User size={16} /> : <Bot size={16} />}
                  </div>
                  <p className="text-sm whitespace-pre-wrap">{m.text}</p>
                </div>
              </div>
            ))}
            {isLoading && (
              <div className="flex justify-start">
                <div className="bg-white p-3 rounded-2xl rounded-tl-none border border-indigo-100 shadow-sm">
                  <span className="flex gap-1">
                    <span className="w-1.5 h-1.5 bg-indigo-400 rounded-full animate-bounce"></span>
                    <span className="w-1.5 h-1.5 bg-indigo-400 rounded-full animate-bounce delay-75"></span>
                    <span className="w-1.5 h-1.5 bg-indigo-400 rounded-full animate-bounce delay-150"></span>
                  </span>
                </div>
              </div>
            )}
          </div>

          <div className="p-4 bg-white border-t flex gap-2">
            <input 
              value={input}
              onChange={(e) => setInput(e.target.value)}
              onKeyDown={(e) => e.key === 'Enter' && handleSend()}
              placeholder="Pergunte sobre a história..."
              className="flex-1 border border-slate-200 rounded-lg px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-indigo-500"
            />
            <button 
              onClick={handleSend}
              disabled={isLoading}
              className="bg-indigo-600 text-white p-2 rounded-lg hover:bg-indigo-700 disabled:opacity-50 transition-colors"
            >
              <Send size={18} />
            </button>
          </div>
        </div>
      )}
    </div>
  );
};

