            </div>
          </div>
        ))}
      </div>

      {/* Modal Detail */}
      {selectedVeteran && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-indigo-950/80 backdrop-blur-sm animate-in fade-in">
          <div className="bg-white w-full max-w-3xl rounded-3xl overflow-hidden shadow-2xl relative animate-in zoom-in duration-300">
