                <button 
                  type="button" 
                  onClick={() => setTranscription('')}
                  className="text-[10px] text-red-500 font-bold uppercase hover:underline"
                >
                  Limpar Transcrição
                </button>
              )}
            </div>
            <textarea 
              rows={6}
              value={transcription}
              onChange={(e) => setTranscription(e.target.value)}
              placeholder="Escreva aqui os detalhes da sua história ou use o microfone abaixo para transcrever..."
              className="w-full px-4 py-3 rounded-xl border border-slate-200 focus:ring-2 focus:ring-indigo-500 outline-none transition-all resize-none"
            ></textarea>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
            <div className="p-6 border-2 border-dashed border-slate-200 rounded-2xl flex flex-col items-center justify-center gap-3 hover:border-indigo-400 hover:bg-indigo-50 transition-all cursor-pointer group">
              <Camera className="text-slate-400 group-hover:text-indigo-600" size={32} />
              <span className="text-xs font-bold text-slate-500 group-hover:text-indigo-900">Anexar Fotos</span>
              <input type="file" className="hidden" accept="image/*" />
