            <div 
              onClick={startTranscription}
              className={`p-6 border-2 border-dashed rounded-2xl flex flex-col items-center justify-center gap-3 transition-all cursor-pointer group ${
                isRecording ? 'border-red-500 bg-red-50 shadow-inner' : 'border-slate-200 hover:border-indigo-400 hover:bg-indigo-50'
