            >
              {isRecording ? <StopCircle className="text-red-600 animate-pulse" size={32} /> : <Mic className="text-slate-400 group-hover:text-indigo-600" size={32} />}
              <span className={`text-xs font-bold ${isRecording ? 'text-red-900' : 'text-slate-500 group-hover:text-indigo-900'}`}>
                {isRecording ? 'Ouvindo... Clique para parar' : 'Transcrição de Voz'}
              </span>
            </div>
            <div className="p-6 border-2 border-dashed border-slate-200 rounded-2xl flex flex-col items-center justify-center gap-3 hover:border-indigo-400 hover:bg-indigo-50 transition-all cursor-pointer group">
              <Upload className="text-slate-400 group-hover:text-indigo-600" size={32} />
              <span className="text-xs font-bold text-slate-500 group-hover:text-indigo-900">Outros Arquivos</span>
            </div>
          </div>

          <div className="pt-8 border-t border-slate-100 flex flex-col sm:flex-row items-center justify-between gap-6">
            <div className="flex items-center gap-3 text-slate-500 text-xs italic">
                <FileText size={16} className="shrink-0" />
                <span>Ao enviar, você autoriza o uso desta memória para fins culturais no APP FESP.</span>
            </div>
            <button 
              type="submit"
              className="w-full sm:w-auto px-10 py-4 bg-indigo-900 text-white font-bold rounded-full hover:bg-indigo-800 transition-all shadow-xl flex items-center justify-center gap-3 group"
            >
              Enviar para Curadoria <Send size={18} className="group-hover:translate-x-1 transition-transform"/>
            </button>
          </div>
        </form>
      </div>
    </div>
  );
};

