import React, { useState, useRef } from 'react';
import { MOCK_VETERANS } from '../constants';
import { Veteran } from '../types';
import { Search, Filter, Volume2, Info, X, Music, Upload, Play, Pause, Trash2 } from 'lucide-react';
import { speakMemory } from '../services/geminiService';

const GalleryPage: React.FC = () => {
  const [veterans, setVeterans] = useState<Veteran[]>(MOCK_VETERANS);
  const [filter, setFilter] = useState<string>('Todos');
  const [search, setSearch] = useState('');
  const [selectedVeteran, setSelectedVeteran] = useState<Veteran | null>(null);
  const [isSpeaking, setIsSpeaking] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const [uploadingForId, setUploadingForId] = useState<string | null>(null);

  const categories = ['Todos', 'Guarda Territorial', 'PMRR', 'Pioneiros'];

  const filteredVeterans = veterans.filter(v => {
    const matchesFilter = filter === 'Todos' || v.category === filter;
    const matchesSearch = v.name.toLowerCase().includes(search.toLowerCase()) || 
                          v.rank.toLowerCase().includes(search.toLowerCase());
    return matchesFilter && matchesSearch;
  });

  const handleSpeak = async (text: string) => {
    if (isSpeaking) return;
    setIsSpeaking(true);

    try {
      const audioData = await speakMemory(text);
      if (audioData) {
        const AudioContextClass = (window as any).AudioContext || (window as any).webkitAudioContext;
        if (!AudioContextClass) {
          throw new Error("Navegador não suporta áudio.");
        }

        const ctx = new AudioContextClass();
        const audioBuffer = await decodeAudioData(audioData, ctx, 24000, 1);
        const source = ctx.createBufferSource();
        source.buffer = audioBuffer;
        source.connect(ctx.destination);
        source.onended = () => {
          setIsSpeaking(false);
          ctx.close();
        };
        source.start();
      } else {
        setIsSpeaking(false);
      }
    } catch (error) {
      console.error("Audio Playback Error:", error);
      setIsSpeaking(false);
    }
  };

  async function decodeAudioData(data: Uint8Array, ctx: AudioContext, sampleRate: number, numChannels: number): Promise<AudioBuffer> {
    const dataInt16 = new Int16Array(data.buffer, data.byteOffset, data.length / 2);
    const frameCount = dataInt16.length / numChannels;
    const buffer = ctx.createBuffer(numChannels, frameCount, sampleRate);
    for (let channel = 0; channel < numChannels; channel++) {
      const channelData = buffer.getChannelData(channel);
      for (let i = 0; i < frameCount; i++) {
        channelData[i] = dataInt16[i * numChannels + channel] / 32768.0;
      }
    }
    return buffer;
  }

  const handleAudioUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file && uploadingForId) {
      const audioUrl = URL.createObjectURL(file);
      setVeterans(prev => prev.map(v => v.id === uploadingForId ? { ...v, audioUrl } : v));
      if (selectedVeteran?.id === uploadingForId) {
        setSelectedVeteran({ ...selectedVeteran, audioUrl });
      }
      setUploadingForId(null);
    }
  };

  const removeAudio = (id: string) => {
    setVeterans(prev => prev.map(v => v.id === id ? { ...v, audioUrl: undefined } : v));
    if (selectedVeteran?.id === id) {
      setSelectedVeteran({ ...selectedVeteran, audioUrl: undefined });
    }
  };

  const triggerUpload = (id: string) => {
    setUploadingForId(id);
    fileInputRef.current?.click();
  };

  const AudioPlayer = ({ url, compact = false }: { url: string, compact?: boolean }) => {
    const [playing, setPlaying] = useState(false);
    const audioRef = useRef<HTMLAudioElement>(null);

    const toggle = () => {
      if (audioRef.current) {
        if (playing) audioRef.current.pause();
        else audioRef.current.play();
        setPlaying(!playing);
      }
    };

    return (
      <div className={`flex items-center gap-3 ${compact ? 'bg-indigo-900/10' : 'bg-indigo-50'} p-3 rounded-xl border border-indigo-100`}>
        <audio ref={audioRef} src={url} onEnded={() => setPlaying(false)} className="hidden" />
        <button 
          onClick={toggle}
          className={`${compact ? 'w-8 h-8' : 'w-10 h-10'} bg-indigo-900 text-white rounded-full flex items-center justify-center hover:bg-indigo-800 transition-all`}
        >
          {playing ? <Pause size={compact ? 14 : 18} /> : <Play size={compact ? 14 : 18} className="ml-0.5" />}
        </button>
        <div className="flex-grow">
          <p className="text-[10px] font-bold text-indigo-900 uppercase tracking-tighter">Áudio do Veterano</p>
          <div className="h-1 bg-indigo-200 rounded-full mt-1 overflow-hidden">
            <div className={`h-full bg-indigo-900 transition-all duration-300 ${playing ? 'animate-pulse w-full' : 'w-0'}`}></div>
          </div>
        </div>
      </div>
    );
  };

  return (
    <div className="py-12 px-4 max-w-7xl mx-auto animate-in fade-in duration-500">
      <input 
        type="file" 
        ref={fileInputRef} 
        onChange={handleAudioUpload} 
        accept="audio/*" 
        className="hidden" 
      />

      <div className="mb-12">
        <h1 className="text-4xl font-bold text-indigo-950 serif-font mb-4">Galeria de Veteranos</h1>
        <p className="text-slate-600 max-w-2xl">Homenageamos aqui os homens e mulheres que dedicaram suas vidas à segurança e ao progresso de Roraima.</p>
      </div>

      <div className="flex flex-col md:flex-row gap-4 mb-10">
        <div className="relative flex-grow">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
          <input 
            type="text" 
            placeholder="Buscar por nome ou posto..."
            className="w-full pl-10 pr-4 py-3 bg-white border border-slate-200 rounded-xl focus:ring-2 focus:ring-indigo-500 outline-none shadow-sm"
            value={search}
            onChange={(e) => setSearch(e.target.value)}
          />
        </div>
        <div className="flex gap-2 overflow-x-auto pb-2 md:pb-0 no-scrollbar">
          {categories.map(cat => (
            <button
              key={cat}
              onClick={() => setFilter(cat)}
              className={`px-6 py-3 rounded-xl font-medium whitespace-nowrap transition-all ${
                filter === cat 
                  ? 'bg-indigo-900 text-white shadow-lg' 
                  : 'bg-white text-slate-600 border border-slate-200 hover:bg-slate-50'
              }`}
            >
              {cat}
            </button>
          ))}
        </div>
      </div>

      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-8">
        {filteredVeterans.map(v => (
          <div 
            key={v.id} 
            className="group bg-white rounded-2xl overflow-hidden shadow-md hover:shadow-2xl transition-all border border-slate-100 flex flex-col"
          >
            <div className="relative h-64 overflow-hidden">
              <img 
                src={v.photoUrl} 
                alt={v.name} 
                className="w-full h-full object-cover group-hover:scale-110 transition-transform duration-500 grayscale group-hover:grayscale-0"
              />
              <div className="absolute top-4 right-4 bg-indigo-900/90 text-white px-3 py-1 rounded-full text-xs font-bold backdrop-blur-sm">
                {v.category}
              </div>
            </div>
            <div className="p-6 flex-grow flex flex-col">
              <div className="flex justify-between items-start mb-1">
                <span className="text-amber-600 font-bold text-sm uppercase">{v.rank}</span>
                {v.audioUrl && (
                  <Music size={16} className="text-indigo-600 animate-bounce" />
                )}
              </div>
              <h3 className="text-2xl font-bold text-indigo-950 serif-font mb-2">{v.name}</h3>
              <p className="text-slate-500 text-sm mb-4 font-medium flex items-center gap-2">
                <Volume2 size={14} /> {v.period} • {v.unit}
              </p>

              <div className="flex-grow">
                <p className="text-slate-600 text-sm line-clamp-3 mb-4 leading-relaxed">
                  {v.bio}
                </p>
                {v.audioUrl && <AudioPlayer url={v.audioUrl} compact />}
              </div>

              <div className="mt-6 flex flex-wrap gap-3">
                <button 
                  onClick={() => setSelectedVeteran(v)}
                  className="flex-1 bg-indigo-50 text-indigo-900 py-2.5 rounded-xl font-bold hover:bg-indigo-100 transition-colors flex items-center justify-center gap-2"
                >
                  <Info size={16}/> Ver História
                </button>
                <div className="flex gap-2 w-full sm:w-auto">
                  {!v.audioUrl ? (
                    <button 
                      onClick={() => triggerUpload(v.id)}
                      className="flex-1 sm:flex-none px-4 py-2.5 bg-slate-100 text-slate-600 rounded-xl flex items-center justify-center hover:bg-indigo-900 hover:text-white transition-all group/btn"
                      title="Adicionar Áudio"
                    >
                      <Upload size={18} />
                    </button>
                  ) : (
                    <button 
                      onClick={() => removeAudio(v.id)}
                      className="flex-1 sm:flex-none px-4 py-2.5 bg-red-50 text-red-600 rounded-xl flex items-center justify-center hover:bg-red-600 hover:text-white transition-all"
                      title="Remover Áudio"
                    >
                      <Trash2 size={18} />
                    </button>
                  )}
                  <button 
                    onClick={() => handleSpeak(`${v.rank} ${v.name}. ${v.bio}`)}
                    disabled={isSpeaking}
                    className="flex-1 sm:flex-none px-4 py-2.5 bg-amber-500 text-indigo-950 rounded-xl flex items-center justify-center hover:bg-amber-600 transition-colors disabled:opacity-50"
                    title="Ouvir Resumo AI"
                  >
                    <Volume2 size={20} className={isSpeaking ? 'animate-pulse' : ''}/>
                  </button>
                </div>
              </div>
            </div>
          </div>
        ))}
      </div>

      {/* Modal Detail */}
      {selectedVeteran && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-indigo-950/80 backdrop-blur-sm animate-in fade-in">
          <div className="bg-white w-full max-w-4xl rounded-3xl overflow-hidden shadow-2xl relative animate-in zoom-in duration-300">
            <button 
              onClick={() => setSelectedVeteran(null)}
              className="absolute top-4 right-4 p-2 bg-slate-100 rounded-full hover:bg-slate-200 z-10"
            >
              <X size={24} />
            </button>
            <div className="flex flex-col md:flex-row h-full max-h-[90vh] overflow-y-auto md:overflow-hidden">
              <div className="md:w-5/12">
                <img 
                  src={selectedVeteran.photoUrl} 
                  alt={selectedVeteran.name} 
                  className="w-full h-full object-cover min-h-[400px]"
                />
              </div>
              <div className="md:w-7/12 p-8 md:p-12 overflow-y-auto flex flex-col">
                <span className="text-amber-600 font-bold uppercase tracking-widest text-sm mb-2 block">{selectedVeteran.rank}</span>
                <h2 className="text-4xl md:text-5xl font-bold text-indigo-950 serif-font mb-6">{selectedVeteran.name}</h2>
                <div className="flex flex-wrap gap-4 mb-8 text-sm text-slate-500 font-medium">
                   <div className="bg-slate-100 px-4 py-2 rounded-xl flex items-center gap-2"><Shield size={14}/> {selectedVeteran.unit}</div>
                   <div className="bg-slate-100 px-4 py-2 rounded-xl flex items-center gap-2"><History size={14}/> {selectedVeteran.period}</div>
                </div>

                <div className="prose prose-indigo max-w-none flex-grow">
                  <h4 className="font-bold text-indigo-950 mb-4 uppercase tracking-widest text-xs">Biografia e Depoimento</h4>
                  <p className="text-slate-700 leading-relaxed text-lg mb-8 italic border-l-4 border-amber-500 pl-6 bg-amber-50/50 py-4 rounded-r-2xl">
                    "{selectedVeteran.bio}"
                  </p>

                  {selectedVeteran.audioUrl ? (
                    <div className="mb-8">
                      <p className="text-sm font-bold text-indigo-950 mb-3 flex items-center gap-2"><Music size={16}/> Registro de Voz Original</p>
                      <AudioPlayer url={selectedVeteran.audioUrl} />
                    </div>
                  ) : (
                    <div className="mb-8 p-6 border-2 border-dashed border-slate-200 rounded-3xl text-center">
                      <p className="text-sm text-slate-500 mb-4">Nenhum áudio de depoimento anexado.</p>
                      <button 
                        onClick={() => triggerUpload(selectedVeteran.id)}
                        className="bg-indigo-900 text-white px-6 py-2 rounded-full text-sm font-bold hover:bg-indigo-800 transition-all flex items-center gap-2 mx-auto"
                      >
                        <Upload size={16}/> Anexar Áudio
                      </button>
                    </div>
                  )}

                  <p className="text-slate-600 leading-relaxed">
                    Este registro histórico preserva a memória institucional através do relato direto de quem vivenciou os marcos da segurança pública em Roraima.
                  </p>
                </div>

                <div className="mt-8 pt-8 border-t border-slate-100 flex flex-wrap gap-4">
                  <button 
                    onClick={() => handleSpeak(`${selectedVeteran.bio}`)}
                    disabled={isSpeaking}
                    className="flex-1 bg-indigo-900 text-white py-4 rounded-2xl font-bold flex items-center justify-center gap-3 hover:bg-indigo-800 transition-all shadow-xl shadow-indigo-900/20"
                  >
                    <Volume2 size={24} className={isSpeaking ? 'animate-pulse' : ''} /> Ouvir Narrativa AI
                  </button>
                  {selectedVeteran.audioUrl && (
                    <button 
                      onClick={() => removeAudio(selectedVeteran.id)}
                      className="p-4 bg-red-50 text-red-600 rounded-2xl hover:bg-red-600 hover:text-white transition-all"
                      title="Excluir Áudio"
                    >
                      <Trash2 size={24} />
                    </button>
                  )}
                </div>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

