import { GoogleGenAI, Type, Modality } from "@google/genai";

export const chatWithMemoryBot = async (history: string[], userMessage: string) => {
  const apiKey = process.env.API_KEY;
  if (!apiKey) return "Serviço de IA não configurado.";

  const ai = new GoogleGenAI({ apiKey });
  const model = "gemini-3-flash-preview";

  const systemInstruction = `
    Você é o 'Bot da Memória', o assistente de IA do Museu Digital da Memória Viva da Caserna (PMRR).

    DIRETRIZES DE COMPORTAMENTO:
    1. Use linguagem técnico-administrativa, clara, objetiva e institucional.
    2. Organize as respostas em seções ou checklists quando apropriado.
    3. Seu foco é a história dos policiais da reserva, veteranos da Guarda Territorial e PMRR de Roraima.
    4. Baseie seu tom na preservação da memória afetiva e institucional.
    5. Nunca emita pareceres jurídicos definitivos. A decisão final é sempre do gestor ou autoridade competente.

    ASSINATURA OBRIGATÓRIA EM CADA RESPOSTA:
    "Esta informação é um apoio técnico. A decisão final é do gestor responsável.
    Documento gerado pelo Museu Digital da Memória Viva da Caserna – Desenvolvido por João Paulo Silva Dantas"
  `;

  try {
    const response = await ai.models.generateContent({
      model,
      contents: [
        { role: 'user', parts: [{ text: `Histórico da conversa:\n${history.join('\n')}\n\nNova mensagem do usuário: ${userMessage}` }] }
      ],
      config: {
        systemInstruction,
        temperature: 0.5,
      }
    });
    return response.text || "Desculpe, não consegui processar sua solicitação técnica no momento.";
  } catch (error) {
    console.error("Gemini Chat Error:", error);
    return "Erro ao conectar com a base de dados da Memória Viva.";
  }
};

export const speakMemory = async (text: string): Promise<Uint8Array | null> => {
  const apiKey = process.env.API_KEY;
  if (!apiKey) return null;
  const ai = new GoogleGenAI({ apiKey });

  try {
    const response = await ai.models.generateContent({
      model: "gemini-2.5-flash-preview-tts",
      contents: [{ parts: [{ text: `Leia de forma solene e administrativa: ${text}` }] }],
      config: {
        responseModalities: [Modality.AUDIO],
        speechConfig: {
          voiceConfig: {
            prebuiltVoiceConfig: { voiceName: 'Kore' },
          },
        },
      },
    });

    const base64Audio = response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;
    if (base64Audio) {
      const binaryString = atob(base64Audio);
      const len = binaryString.length;
      const bytes = new Uint8Array(len);
      for (let i = 0; i < len; i++) {
        bytes[i] = binaryString.charCodeAt(i);
      }
      return bytes;
    }
  } catch (error) {
    console.error("Gemini TTS Error:", error);
  }
  return null;
};

