      const updated = await db.getVeteranos();
      setVeteranos(updated);
      if (selectedVeteran?.id === uploadingForId) {
        setSelectedVeteran({ ...selectedVeteran, audio_url: audioUrl });
      }
      setUploadingForId(null);
    }
  };

  const removeAudio = async (id: string) => {
    await db.updateVeteranoAudio(id, '');
