import React, { useState, useRef } from 'react';
import { db } from '../services/databaseService';
import { Upload, Mic, Camera, FileText, Send, CheckCircle, StopCircle } from 'lucide-react';

const SubmitPage: React.FC = () => {
  const [submitted, setSubmitted] = useState(false);
  const [isRecording, setIsRecording] = useState(false);
  const [transcription, setTranscription] = useState('');
  const [nome, setNome] = useState('');
  const [email, setEmail] = useState('');
  const [titulo, setTitulo] = useState('');
  const recognitionRef = useRef<any>(null);

  const startTranscription = () => {
    if (isRecording) {
      if (recognitionRef.current) recognitionRef.current.stop();
      setIsRecording(false);
      return;
    }

    const SpeechRecognitionClass = (window as any).SpeechRecognition || (window as any).webkitSpeechRecognition;
    if (!SpeechRecognitionClass) {
      alert("Seu navegador não suporta reconhecimento de voz.");
      return;
    }

    try {
      const recognition = new SpeechRecognitionClass();
      recognition.lang = 'pt-BR';
      recognition.continuous = true;
      recognition.interimResults = true;
      recognition.onresult = (event: any) => {
        let currentTranscription = '';
        for (let i = event.resultIndex; i < event.results.length; ++i) {
          if (event.results[i].isFinal) currentTranscription += event.results[i][0].transcript;
        }
        if (currentTranscription) setTranscription(prev => prev + ' ' + currentTranscription.trim());
      };
      recognition.onstart = () => setIsRecording(true);
      recognition.onend = () => setIsRecording(false);
      recognitionRef.current = recognition;
      recognition.start();
    } catch (e) {
      console.error(e);
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    await db.addContribuicao({
      nome,
      email,
      relato: transcription
    });
    setSubmitted(true);
  };

  if (submitted) {
    return (
      <div className="py-20 px-4 max-w-2xl mx-auto text-center animate-in zoom-in duration-500">
        <div className="bg-white p-12 rounded-[3rem] shadow-2xl border border-indigo-50">
          <div className="w-24 h-24 bg-green-100 text-green-600 rounded-full flex items-center justify-center mx-auto mb-8">
            <CheckCircle size={48} />
          </div>
          <h1 className="text-3xl font-bold text-indigo-950 serif-font mb-4">Contribuição Recebida!</h1>
          <p className="text-slate-600 mb-10 leading-relaxed">Sua história foi salva no banco de dados e aguarda aprovação da curadoria.</p>
          <button onClick={() => setSubmitted(false)} className="bg-indigo-900 text-white px-8 py-3 rounded-full font-bold">Enviar Outra</button>
        </div>
      </div>
    );
  }

  return (
    <div className="py-12 px-4 max-w-4xl mx-auto animate-in fade-in duration-500">
      <div className="mb-12 text-center">
        <h1 className="text-4xl font-bold text-indigo-950 serif-font mb-4">Envie Sua História</h1>
      </div>

      <div className="bg-white rounded-[2rem] shadow-xl border border-slate-100 overflow-hidden">
        <form onSubmit={handleSubmit} className="p-8 md:p-12 space-y-8">
          <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
            <div className="space-y-4">
              <label className="block text-sm font-bold text-indigo-900 uppercase">Título</label>
              <input required type="text" value={titulo} onChange={e => setTitulo(e.target.value)} className="w-full px-4 py-3 rounded-xl border border-slate-200" />
            </div>
            <div className="space-y-4">
              <label className="block text-sm font-bold text-indigo-900 uppercase">Seu Nome</label>
              <input required type="text" value={nome} onChange={e => setNome(e.target.value)} className="w-full px-4 py-3 rounded-xl border border-slate-200" />
            </div>
          </div>
          <div className="space-y-4">
            <label className="block text-sm font-bold text-indigo-900 uppercase">E-mail</label>
            <input required type="email" value={email} onChange={e => setEmail(e.target.value)} className="w-full px-4 py-3 rounded-xl border border-slate-200" />
          </div>
          <div className="space-y-4">
            <label className="block text-sm font-bold text-indigo-900 uppercase">Relato</label>
            <textarea rows={6} value={transcription} onChange={e => setTranscription(e.target.value)} className="w-full px-4 py-3 rounded-xl border border-slate-200 resize-none" />
          </div>
          <div className="flex justify-center gap-4">
            <button type="button" onClick={startTranscription} className={`p-4 rounded-full border-2 border-dashed ${isRecording ? 'border-red-500 bg-red-50' : 'border-slate-200'}`}>
              {isRecording ? <StopCircle className="text-red-500" /> : <Mic />}
            </button>
          </div>
          <button type="submit" className="w-full py-4 bg-indigo-900 text-white font-bold rounded-full flex items-center justify-center gap-3">
            Salvar Contribuição <Send size={18} />
          </button>
        </form>
      </div>
    </div>
  );
};

