import React, { useState, useRef, useEffect } from 'react';
import { db } from '../services/databaseService';
import { Veterano } from '../types';
import { Search, Volume2, Info, X, Music, Upload, Play, Pause, Trash2, Shield, History } from 'lucide-react';
import { speakMemory } from '../services/geminiService';

const GalleryPage: React.FC = () => {
  const [veteranos, setVeteranos] = useState<Veterano[]>([]);
  const [filter, setFilter] = useState<string>('Todos');
  const [search, setSearch] = useState('');
  const [selectedVeteran, setSelectedVeteran] = useState<Veterano | null>(null);
  const [isSpeaking, setIsSpeaking] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const [uploadingForId, setUploadingForId] = useState<string | null>(null);

  // Estado para controlar qual áudio está tocando globalmente na galeria
  const [playingAudioId, setPlayingAudioId] = useState<string | null>(null);
  const audioRefs = useRef<{ [key: string]: HTMLAudioElement | null }>({});

  useEffect(() => {
    db.getVeteranos().then(setVeteranos);
  }, []);

  const categories = ['Todos', 'Guarda Territorial', 'PMRR'];

  const filteredVeterans = veteranos.filter(v => {
    const matchesFilter = filter === 'Todos' || v.origem === filter;
    const matchesSearch = v.name.toLowerCase().includes(search.toLowerCase()) || 
                          (v.patente || '').toLowerCase().includes(search.toLowerCase());
    return matchesFilter && matchesSearch;
  });

  const handleSpeak = async (text: string) => {
    if (isSpeaking) return;
    setIsSpeaking(true);

    try {
      const audioData = await speakMemory(text);
      if (audioData) {
        const AudioContextClass = (window as any).AudioContext || (window as any).webkitAudioContext;
        const ctx = new AudioContextClass();
        const audioBuffer = await decodeAudioData(audioData, ctx, 24000, 1);
        const source = ctx.createBufferSource();
        source.buffer = audioBuffer;
        source.connect(ctx.destination);
        source.onended = () => {
          setIsSpeaking(false);
          ctx.close();
        };
        source.start();
      } else {
        setIsSpeaking(false);
      }
    } catch (error) {
      console.error("Audio Playback Error:", error);
      setIsSpeaking(false);
    }
  };

  async function decodeAudioData(data: Uint8Array, ctx: AudioContext, sampleRate: number, numChannels: number): Promise<AudioBuffer> {
    const dataInt16 = new Int16Array(data.buffer, data.byteOffset, data.length / 2);
    const frameCount = dataInt16.length / numChannels;
    const buffer = ctx.createBuffer(numChannels, frameCount, sampleRate);
    for (let channel = 0; channel < numChannels; channel++) {
      const channelData = buffer.getChannelData(channel);
      for (let i = 0; i < frameCount; i++) {
        channelData[i] = dataInt16[i * numChannels + channel] / 32768.0;
      }
    }
    return buffer;
  }

  const handleAudioUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file && uploadingForId) {
      const audioUrl = URL.createObjectURL(file);
      await db.updateVeteranoAudio(uploadingForId, audioUrl);
      const updated = await db.getVeteranos();
      setVeteranos(updated);
      if (selectedVeteran?.id === uploadingForId) {
        setSelectedVeteran({ ...selectedVeteran, audio_url: audioUrl });
      }
      setUploadingForId(null);
    }
  };

  const removeAudio = async (id: string) => {
    if (playingAudioId === id) {
        audioRefs.current[id]?.pause();
        setPlayingAudioId(null);
    }
    await db.updateVeteranoAudio(id, '');
    const updated = await db.getVeteranos();
    setVeteranos(updated);
    if (selectedVeteran?.id === id) {
      setSelectedVeteran({ ...selectedVeteran, audio_url: undefined });
    }
  };

  const triggerUpload = (id: string) => {
    setUploadingForId(id);
    fileInputRef.current?.click();
  };

  const toggleDepoimento = (id: string) => {
    const audio = audioRefs.current[id];
    if (!audio) return;

    if (playingAudioId === id) {
      audio.pause();
      setPlayingAudioId(null);
    } else {
      // Para qualquer outro áudio que esteja tocando
      if (playingAudioId && audioRefs.current[playingAudioId]) {
        audioRefs.current[playingAudioId]?.pause();
      }
      audio.play();
      setPlayingAudioId(id);
    }
  };

  return (
