  useEffect(() => {
    const loadData = async () => {
      const vs = await db.getVeteranos();
      setVeteranos(vs);

      const hMap: {[key: string]: Historia[]} = {};
      for (const v of vs) {
        hMap[v.id] = await db.getHistoriasByVeterano(v.id);
      }
