import React, { useState, useRef, useEffect } from 'react';
import { db } from '../services/databaseService';
import { Profile, Veterano } from '../types';
import { Upload, Mic, Send, CheckCircle, StopCircle, LogIn, FileAudio, FileVideo, FileText, User } from 'lucide-react';
import { Link } from 'react-router-dom';
import { AppRoute } from '../types';

interface SubmitPageProps {
  user: Profile | null;
}

const SubmitPage: React.FC<SubmitPageProps> = ({ user }) => {
  const [submitted, setSubmitted] = useState(false);
  const [isRecording, setIsRecording] = useState(false);
  const [transcription, setTranscription] = useState('');
  const [titulo, setTitulo] = useState('');
  const [nomeVeterano, setNomeVeterano] = useState('');
  const [tipo, setTipo] = useState<'texto' | 'áudio' | 'vídeo'>('texto');
  const [veteranos, setVeteranos] = useState<Veterano[]>([]);
  const [selectedVeteranoId, setSelectedVeteranoId] = useState('');
  const [file, setFile] = useState<File | null>(null);
  const [uploading, setUploading] = useState(false);

  const recognitionRef = useRef<any>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    db.getVeteranos().then(setVeteranos);
  }, []);

  const startTranscription = () => {
    if (isRecording) {
      if (recognitionRef.current) recognitionRef.current.stop();
      setIsRecording(false);
      return;
    }

    const SpeechRecognitionClass = (window as any).SpeechRecognition || (window as any).webkitSpeechRecognition;
    if (!SpeechRecognitionClass) {
      alert("Seu navegador não suporta reconhecimento de voz.");
      return;
    }

    try {
      const recognition = new SpeechRecognitionClass();
      recognition.lang = 'pt-BR';
      recognition.continuous = true;
      recognition.onresult = (event: any) => {
        let currentTranscription = '';
        for (let i = event.resultIndex; i < event.results.length; ++i) {
          if (event.results[i].isFinal) currentTranscription += event.results[i][0].transcript;
        }
        if (currentTranscription) setTranscription(prev => prev + ' ' + currentTranscription.trim());
      };
      recognition.onstart = () => setIsRecording(true);
      recognition.onend = () => setIsRecording(false);
      recognitionRef.current = recognition;
      recognition.start();
    } catch (e) {
      console.error(e);
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!user) return;

    setUploading(true);
    let arquivoUrl = '';

    if (file) {
      arquivoUrl = await db.uploadFile(file);
    }

    // Se um veterano for selecionado da lista, usa o nome dele, senão usa o campo de texto
    const nomeFinal = selectedVeteranoId 
      ? (veteranos.find(v => v.id === selectedVeteranoId)?.nome || nomeVeterano)
      : nomeVeterano;

    await db.addHistoria({
      titulo,
      nome_veterano: nomeFinal,
      descricao: transcription,
      tipo,
      veterano_id: selectedVeteranoId || null,
      arquivo_url: arquivoUrl,
      data: new Date().toISOString().split('T')[0]
    });

    setUploading(false);
    setSubmitted(true);
  };

  if (!user) {
    return (
      <div className="py-20 px-4 max-w-2xl mx-auto text-center animate-in fade-in">
        <div className="bg-white p-12 rounded-[3rem] shadow-2xl border border-indigo-50">
          <div className="w-20 h-20 bg-amber-100 text-amber-600 rounded-full flex items-center justify-center mx-auto mb-6">
            <LogIn size={40} />
          </div>
          <h1 className="text-3xl font-bold text-indigo-950 serif-font mb-4">Acesso Necessário</h1>
          <p className="text-slate-600 mb-8">Para preservar a autenticidade do nosso acervo, apenas usuários identificados podem enviar histórias.</p>
          <Link to={AppRoute.LOGIN} className="inline-flex items-center gap-2 bg-indigo-900 text-white px-8 py-3 rounded-full font-bold hover:bg-indigo-800 transition-all">
            Entrar no Portal
          </Link>
        </div>
      </div>
    );
  }

  if (submitted) {
    return (
      <div className="py-20 px-4 max-w-2xl mx-auto text-center animate-in zoom-in">
        <div className="bg-white p-12 rounded-[3rem] shadow-2xl border border-indigo-50">
          <div className="w-24 h-24 bg-green-100 text-green-600 rounded-full flex items-center justify-center mx-auto mb-8">
            <CheckCircle size={48} />
          </div>
          <h1 className="text-3xl font-bold text-indigo-950 serif-font mb-4">Memória Enviada!</h1>
          <p className="text-slate-600 mb-10">Sua contribuição está em nossa Central de Curadoria e será publicada após verificação técnica.</p>
          <button onClick={() => setSubmitted(false)} className="bg-indigo-900 text-white px-8 py-3 rounded-full font-bold">Enviar Nova Memória</button>
        </div>
      </div>
    );
  }

  return (
    <div className="py-12 px-4 max-w-4xl mx-auto animate-in fade-in">
      <div className="mb-12 text-center">
        <h1 className="text-4xl font-bold text-indigo-950 serif-font mb-4">Contribuir com o Acervo</h1>
        <p className="text-slate-500">Compartilhe relatos, documentos ou memórias da caserna.</p>
      </div>

      <div className="bg-white rounded-[2rem] shadow-xl border border-slate-100 overflow-hidden">
        <form onSubmit={handleSubmit} className="p-8 md:p-12 space-y-8">
          <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
            <div className="space-y-2">
              <label className="text-xs font-bold text-indigo-900 uppercase tracking-widest px-1">Título da Memória</label>
              <input 
                required 
                type="text" 
                value={titulo} 
                onChange={e => setTitulo(e.target.value)} 
                className="w-full px-4 py-4 bg-slate-50 border border-slate-200 rounded-2xl focus:ring-2 focus:ring-indigo-500 outline-none" 
                placeholder="Ex: O dia da inauguração do quartel..."
              />
            </div>
            <div className="space-y-2">
              <label className="text-xs font-bold text-indigo-900 uppercase tracking-widest px-1">Nome do Veterano</label>
              <div className="relative">
                <input 
                  type="text" 
                  value={nomeVeterano} 
                  onChange={e => { setNomeVeterano(e.target.value); setSelectedVeteranoId(''); }} 
                  className="w-full pl-12 pr-4 py-4 bg-slate-50 border border-slate-200 rounded-2xl focus:ring-2 focus:ring-indigo-500 outline-none" 
                  placeholder="Nome completo do veterano"
                  disabled={!!selectedVeteranoId}
                />
                <User size={18} className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400" />
              </div>
            </div>
          </div>

          <div className="space-y-2">
            <label className="text-xs font-bold text-indigo-900 uppercase tracking-widest px-1">Ou vincular a veterano cadastrado</label>
            <select 
              value={selectedVeteranoId}
              onChange={e => setSelectedVeteranoId(e.target.value)}
              className="w-full px-4 py-4 bg-slate-50 border border-slate-200 rounded-2xl focus:ring-2 focus:ring-indigo-500 outline-none"
            >
              <option value="">Selecione um veterano da lista (opcional)...</option>
              {veteranos.map(v => (
                <option key={v.id} value={v.id}>{v.patente} {v.nome}</option>
              ))}
            </select>
            <p className="text-[10px] text-slate-400 italic">Ao selecionar um veterano da lista, o nome acima será ignorado.</p>
          </div>

          <div className="space-y-2">
            <label className="text-xs font-bold text-indigo-900 uppercase tracking-widest px-1">Tipo de Conteúdo</label>
            <div className="flex gap-4">
              {(['texto', 'áudio', 'vídeo'] as const).map(t => (
                <button
                  key={t}
                  type="button"
                  onClick={() => setTipo(t)}
                  className={`flex-1 py-4 rounded-2xl border-2 flex flex-col items-center gap-2 transition-all ${
                    tipo === t ? 'border-indigo-600 bg-indigo-50 text-indigo-900' : 'border-slate-100 bg-white text-slate-400 hover:border-slate-200'
                  }`}
                >
                  {t === 'texto' && <FileText size={24} />}
                  {t === 'áudio' && <FileAudio size={24} />}
                  {t === 'vídeo' && <FileVideo size={24} />}
                  <span className="text-xs font-bold uppercase">{t}</span>
                </button>
              ))}
            </div>
          </div>

          <div className="space-y-2">
            <label className="text-xs font-bold text-indigo-900 uppercase tracking-widest px-1">Relato ou Transcrição</label>
            <div className="relative">
              <textarea 
                rows={6} 
                value={transcription} 
                onChange={e => setTranscription(e.target.value)} 
