import React, { useState, useRef, useEffect } from 'react';
import { db } from '../services/databaseService';
import { Veterano, Historia } from '../types';
import { Search, Volume2, Info, X, Music, Play, Pause, History, Calendar, FileText, Video, Mic } from 'lucide-react';
import { speakMemory } from '../services/geminiService';

const GalleryPage: React.FC = () => {
  const [veteranos, setVeteranos] = useState<Veterano[]>([]);
  const [historias, setHistorias] = useState<{[key: string]: Historia[]}>({});
  const [filter, setFilter] = useState<string>('Todos');
  const [search, setSearch] = useState('');
  const [selectedVeteran, setSelectedVeteran] = useState<Veterano | null>(null);
  const [isSpeaking, setIsSpeaking] = useState(false);

  const [playingAudioId, setPlayingAudioId] = useState<string | null>(null);
  const audioRefs = useRef<{ [key: string]: HTMLAudioElement | null }>({});

  useEffect(() => {
    const loadData = async () => {
      const vs = await db.getVeteranos();
      setVeteranos(vs);

      const hMap: {[key: string]: Historia[]} = {};
      for (const v of vs) {
        hMap[v.id] = await db.getHistoriasByVeterano(v.id);
      }
      setHistorias(hMap);
    };
    loadData();
  }, []);

  const categories = ['Todos', 'Guarda Territorial', 'PMRR'];

  const filteredVeterans = veteranos.filter(v => {
    const matchesFilter = filter === 'Todos' || v.origem === filter;

    const searchTerm = search.toLowerCase();
    const matchesBasic = v.nome.toLowerCase().includes(searchTerm) || 
                         (v.patente || '').toLowerCase().includes(searchTerm);

    const vHistorias = historias[v.id] || [];
    const matchesHistorias = vHistorias.some(h => 
      h.titulo.toLowerCase().includes(searchTerm) || 
      (h.descricao || '').toLowerCase().includes(searchTerm)
    );

    return matchesFilter && (matchesBasic || matchesHistorias);
  });

  const handleSpeak = async (text: string) => {
    if (isSpeaking) return;
    setIsSpeaking(true);

    try {
      const audioData = await speakMemory(text);
      if (audioData) {
        const AudioContextClass = (window as any).AudioContext || (window as any).webkitAudioContext;
        const ctx = new AudioContextClass();
        const dataInt16 = new Int16Array(audioData.buffer, audioData.byteOffset, audioData.length / 2);
        const frameCount = dataInt16.length;
        const buffer = ctx.createBuffer(1, frameCount, 24000);
        const channelData = buffer.getChannelData(0);
        for (let i = 0; i < frameCount; i++) {
          channelData[i] = dataInt16[i] / 32768.0;
        }
        const source = ctx.createBufferSource();
        source.buffer = buffer;
        source.connect(ctx.destination);
        source.onended = () => {
          setIsSpeaking(false);
          ctx.close();
        };
        source.start();
      } else {
        setIsSpeaking(false);
      }
    } catch (error) {
      console.error(error);
      setIsSpeaking(false);
    }
  };

  const toggleAudio = (historiaId: string) => {
    const audio = audioRefs.current[historiaId];
    if (!audio) return;

    if (playingAudioId === historiaId) {
      audio.pause();
      setPlayingAudioId(null);
    } else {
      if (playingAudioId && audioRefs.current[playingAudioId]) {
        audioRefs.current[playingAudioId]?.pause();
      }
      audio.play();
      setPlayingAudioId(historiaId);
    }
  };

  return (
    <div className="py-12 px-4 max-w-7xl mx-auto animate-in fade-in duration-500">
      <div className="mb-12">
        <h1 className="text-4xl font-bold text-indigo-950 serif-font mb-4">Galeria de Veteranos</h1>
        <p className="text-slate-600 max-w-2xl">O conteúdo transcrito de áudios e vídeos agora é indexado em nossa busca global.</p>
      </div>

      <div className="flex flex-col md:flex-row gap-4 mb-10">
        <div className="relative flex-grow">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
          <input 
            type="text" 
            placeholder="Pesquisar por nome, história ou palavras em áudios..."
            className="w-full pl-10 pr-4 py-3 bg-white border border-slate-200 rounded-xl focus:ring-2 focus:ring-indigo-500 outline-none shadow-sm"
            value={search}
            onChange={(e) => setSearch(e.target.value)}
          />
        </div>
        <div className="flex gap-2 overflow-x-auto pb-2 md:pb-0 no-scrollbar">
          {categories.map(cat => (
            <button
              key={cat}
              onClick={() => setFilter(cat)}
              className={`px-6 py-3 rounded-xl font-medium whitespace-nowrap transition-all ${
                filter === cat ? 'bg-indigo-900 text-white shadow-lg' : 'bg-white text-slate-600 border border-slate-200 hover:bg-slate-50'
              }`}
            >
              {cat}
            </button>
          ))}
        </div>
      </div>

      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-8">
        {filteredVeterans.map(v => {
          const vHistorias = historias[v.id] || [];
          const audioHistoria = vHistorias.find(h => h.tipo === 'áudio');
          const videoHistoria = vHistorias.find(h => h.tipo === 'vídeo');

          const matchedStory = search && vHistorias.find(h => 
            h.titulo.toLowerCase().includes(search.toLowerCase()) || 
            (h.descricao || '').toLowerCase().includes(search.toLowerCase())
          );

          return (
            <div key={v.id} className="group bg-white rounded-2xl overflow-hidden shadow-md hover:shadow-2xl transition-all border border-slate-100 flex flex-col relative">
              <div className="relative h-64 overflow-hidden">
                <img src={v.foto_url || 'https://via.placeholder.com/400'} alt={v.nome} className="w-full h-full object-cover grayscale group-hover:grayscale-0 transition-all duration-500" />
                <div className="absolute top-4 right-4 bg-indigo-900/90 text-white px-3 py-1 rounded-full text-xs font-bold">{v.origem}</div>

                {matchedStory && (
                  <div className="absolute bottom-0 inset-x-0 bg-amber-500/90 text-indigo-950 p-2 text-[10px] font-bold uppercase tracking-wider text-center flex items-center justify-center gap-2">
                    {matchedStory.tipo === 'áudio' ? <Music size={12}/> : matchedStory.tipo === 'vídeo' ? <Video size={12}/> : <FileText size={12}/>}
                    Match na história: {matchedStory.titulo}
                  </div>
                )}
              </div>

              <div className="p-6 flex-grow flex flex-col">
                <div className="flex justify-between items-start mb-1">
                  <span className="text-amber-600 font-bold text-sm uppercase">{v.patente}</span>
                  <div className="flex gap-2">
                    {audioHistoria && <Music size={16} className="text-indigo-600 animate-pulse" />}
                    {videoHistoria && <Video size={16} className="text-purple-600" />}
                  </div>
                </div>
                <h3 className="text-xl font-bold text-indigo-950 serif-font mb-2">{v.nome}</h3>
                <p className="text-slate-500 text-[10px] mb-4 font-bold flex items-center gap-2 uppercase tracking-widest">
                  <Calendar size={12} /> Ingresso: {v.data_ingresso}
                </p>

                <div className="flex-grow">
                  <p className="text-slate-600 text-sm line-clamp-3 mb-4 leading-relaxed">
                    {v.bio}
                  </p>
                </div>

                <div className="mt-6 flex flex-wrap gap-3">
                  <button onClick={() => setSelectedVeteran(v)} className="flex-1 bg-indigo-50 text-indigo-900 py-2.5 rounded-xl font-bold hover:bg-indigo-100 transition-colors flex items-center justify-center gap-2">
                    <Info size={16}/> Ver História
                  </button>

                  {audioHistoria?.arquivo_url && (
                    <button 
                      onClick={() => toggleAudio(audioHistoria.id)} 
                      className={`flex-1 py-2.5 rounded-xl font-bold flex items-center justify-center gap-2 transition-all ${
                        playingAudioId === audioHistoria.id 
                        ? 'bg-amber-500 text-indigo-950 scale-105' 
                        : 'bg-indigo-900 text-white hover:bg-indigo-800'
                      }`}
                    >
                      {playingAudioId === audioHistoria.id ? <Pause size={18} /> : <Play size={18} />}
                      Depoimento
                      <audio ref={el => audioRefs.current[audioHistoria.id] = el} src={audioHistoria.arquivo_url} onEnded={() => setPlayingAudioId(null)} className="hidden" />
                    </button>
                  )}

                  <button onClick={() => handleSpeak(`${v.nome}. ${v.bio}`)} disabled={isSpeaking} className="p-2.5 bg-slate-100 text-indigo-950 rounded-xl hover:bg-amber-500 transition-all" title="Narrativa AI">
                    <Volume2 size={20} className={isSpeaking ? 'animate-pulse' : ''}/>
                  </button>
                </div>
              </div>
            </div>
          );
        })}
      </div>

      {selectedVeteran && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-indigo-950/80 backdrop-blur-sm overflow-y-auto">
          <div className="bg-white w-full max-w-4xl rounded-[2.5rem] overflow-hidden shadow-2xl relative my-8">
            <button onClick={() => setSelectedVeteran(null)} className="absolute top-6 right-6 p-2 bg-slate-100/80 backdrop-blur rounded-full hover:bg-slate-200 transition-colors z-20">
              <X size={24} className="text-indigo-900" />
            </button>
            <div className="flex flex-col md:flex-row h-full">
              <div className="md:w-5/12 relative">
                <img src={selectedVeteran.foto_url} alt={selectedVeteran.nome} className="w-full h-full object-cover min-h-[300px] md:min-h-full" />
                <div className="absolute inset-0 bg-gradient-to-t from-indigo-950/60 to-transparent md:hidden"></div>
              </div>
              <div className="md:w-7/12 p-8 md:p-12 overflow-y-auto max-h-[90vh]">
                <div className="mb-8">
                  <span className="text-amber-600 font-bold uppercase tracking-widest text-xs mb-2 block">{selectedVeteran.patente} • {selectedVeteran.origem}</span>
                  <h2 className="text-4xl font-bold text-indigo-950 serif-font mb-6 leading-tight">{selectedVeteran.nome}</h2>
                  <div className="relative">
                    <p className="text-slate-700 leading-relaxed text-lg italic border-l-4 border-amber-500 pl-6 bg-amber-50/30 py-6 rounded-r-3xl">
                      "{selectedVeteran.bio}"
                    </p>
                  </div>
                </div>

                <h4 className="font-bold text-indigo-900 mb-6 flex items-center gap-2 text-xl serif-font border-b border-indigo-50 pb-4">
                  <History size={24} className="text-amber-500" /> Registros de Memória
                </h4>

                <div className="grid grid-cols-1 gap-4">
                  {(historias[selectedVeteran.id] || []).map(h => (
                    <div key={h.id} className="p-6 bg-slate-50 rounded-3xl border border-slate-100 hover:border-indigo-200 transition-all group">
                      <div className="flex justify-between items-start mb-3">
                        <div className="flex items-center gap-3">
                          <div className={`p-2 rounded-xl ${
                            h.tipo === 'áudio' ? 'bg-blue-100 text-blue-600' : 
                            h.tipo === 'vídeo' ? 'bg-purple-100 text-purple-600' : 
                            'bg-amber-100 text-amber-600'
                          }`}>
                            {h.tipo === 'áudio' ? <Mic size={18} /> : 
                             h.tipo === 'vídeo' ? <Video size={18} /> : 
                             <FileText size={18} />}
                          </div>
                          <p className="font-bold text-indigo-950 group-hover:text-indigo-700 transition-colors">{h.titulo}</p>
                        </div>
                        <span className={`text-[9px] uppercase font-black px-2.5 py-1 rounded-full tracking-tighter shadow-sm ${
                          h.tipo === 'áudio' ? 'bg-blue-600 text-white' : 
                          h.tipo === 'vídeo' ? 'bg-purple-600 text-white' : 
                          'bg-amber-600 text-white'
                        }`}>
                          {h.tipo}
                        </span>
                      </div>

                      <div className="relative">
                        <p className="text-sm text-slate-600 leading-relaxed line-clamp-3 group-hover:line-clamp-none transition-all duration-300">
                          {h.descricao}
                        </p>
                        <div className="h-2 w-full bg-transparent group-hover:h-0"></div>
                      </div>

                      {h.arquivo_url && h.tipo === 'áudio' && (
                        <div className="mt-5 p-2 bg-white rounded-2xl shadow-sm border border-slate-100">
                          <audio controls src={h.arquivo_url} className="w-full h-8" />
                        </div>
                      )}

                      {h.arquivo_url && h.tipo === 'vídeo' && (
                        <div className="mt-5 bg-black rounded-2xl overflow-hidden shadow-xl aspect-video flex items-center justify-center">
                          <video 
                            controls 
                            src={h.arquivo_url} 
                            className="w-full h-full object-contain"
                            poster="https://images.unsplash.com/photo-1590402444816-0f283c159359?auto=format&fit=crop&q=80&w=800"
                          >
                            Seu navegador não suporta a tag de vídeo.
                          </video>
                        </div>
                      )}
                    </div>
                  ))}

                  {(!historias[selectedVeteran.id] || historias[selectedVeteran.id].length === 0) && (
                    <div className="text-center py-8 bg-slate-50 rounded-3xl border border-dashed border-slate-200">
                      <p className="text-slate-400 text-sm">Nenhum registro detalhado disponível.</p>
                    </div>
                  )}
                </div>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

