const TimelinePage: React.FC = () => {
  const [timeline, setTimeline] = useState<LinhaDoTempo[]>([]);
  const [historias, setHistorias] = useState<Historia[]>([]);
  const [selectedHistoria, setSelectedHistoria] = useState<Historia | null>(null);

  useEffect(() => {
    const loadData = async () => {
      const [tData, hData] = await Promise.all([
        db.getLinhaDoTempo(),
        db.getHistoriasAprovadas()
      ]);
      setTimeline(tData);
      setHistorias(hData);
    };
    loadData();
  }, []);

  const getHistoriaForMarco = (historiaId?: string) => {
    return historias.find(h => h.id === historiaId);
  };

  return (
    <div className="py-12 px-4 max-w-5xl mx-auto animate-in fade-in duration-500">
      <div className="text-center mb-16">
        <h1 className="text-4xl font-bold text-indigo-950 serif-font mb-4">A Linha do Tempo da Caserna</h1>
        <p className="text-slate-600 max-w-2xl mx-auto">Uma jornada cronológica pelos marcos da Guarda Territorial e de nossas forças militares conectados às histórias reais dos nossos veteranos.</p>
      </div>

      <div className="relative">
        <div className="absolute left-1/2 transform -translate-x-1/2 h-full w-1 bg-indigo-100 hidden md:block"></div>

        <div className="space-y-12 md:space-y-16">
          {timeline.map((event, idx) => {
            const h = getHistoriaForMarco(event.historia_id);
            return (
              <div key={event.id} className={`flex flex-col md:flex-row items-center w-full relative ${idx % 2 === 0 ? 'md:flex-row-reverse' : ''}`}>
                <div className="hidden md:block w-1/2"></div>
                <div className="z-10 bg-white border-4 border-indigo-50 w-12 h-12 rounded-full flex items-center justify-center shadow-lg mb-4 md:mb-0">
                  <Shield size={18} className="text-indigo-600" />
                </div>
                <div className="w-full md:w-1/2 px-4 md:px-8">
                  <div className="bg-white p-6 rounded-3xl shadow-md border-l-4 border-indigo-600 hover:shadow-xl transition-shadow relative overflow-hidden group">
                    <div className="flex items-center justify-between mb-2">
                      <span className="text-2xl font-bold text-indigo-900 serif-font">{event.ano}</span>
                      {h && (
                        <span className="text-[10px] bg-indigo-100 text-indigo-700 font-bold uppercase py-1 px-2 rounded-full flex items-center gap-1">
                          <ExternalLink size={10} /> História Vinculada
