import { Veterano, Historia, LinhaDoTempo, Contribuicao, Profile } from '../types';
import { MOCK_VETERANOS, MOCK_HISTORIAS, MOCK_LINHA_TEMPO, MOCK_CONTRIBUICOES } from '../constants';

class DatabaseService {
  private veteranos: Veterano[] = [...MOCK_VETERANOS];
  private historias: Historia[] = [...MOCK_HISTORIAS];
  private linhaDoTempo: LinhaDoTempo[] = [...MOCK_LINHA_TEMPO];
  private contribuicoes: Contribuicao[] = [...MOCK_CONTRIBUICOES];
  private profiles: Profile[] = [
    { id: 'admin-1', nome: 'João Paulo (Admin)', email: 'admin@memoriaviva.com.br', role: 'admin' },
    { id: 'user-1', nome: 'Veterano Exemplo', email: 'veterano@exemplo.com', role: 'usuario' }
  ];
  private currentUser: Profile | null = null;

  async login(email: string, password: string): Promise<Profile | null> {
    const profile = this.profiles.find(p => p.email === email);
    if (profile) {
      this.currentUser = profile;
      return profile;
    }
    const newProfile: Profile = {
      id: crypto.randomUUID(),
      nome: email.split('@')[0],
      email: email,
      role: email.includes('admin') ? 'admin' : 'usuario'
    };
    this.profiles.push(newProfile);
    this.currentUser = newProfile;
    return newProfile;
  }

  async logout() {
    this.currentUser = null;
  }

  getCurrentUser() {
    return this.currentUser;
  }

  async uploadFile(file: File): Promise<string> {
    return URL.createObjectURL(file);
  }

  // Veteranos
  async getVeteranos() { return this.veteranos; }

  // Histórias
  async getHistorias() {
    return this.historias;
  }

  async getHistoriasAprovadas() {
    return this.historias.filter(h => h.aprovado);
  }

  async getHistoriasByVeterano(veteranoId: string) {
    return this.historias.filter(h => h.veterano_id === veteranoId && h.aprovado);
  }

  async getHistoriasPendentes() {
    return this.historias.filter(h => !h.aprovado);
  }

  async addHistoria(h: Omit<Historia, 'id' | 'created_at' | 'aprovado'>) {
    const newH: Historia = {
      ...h,
      id: crypto.randomUUID(),
      created_at: new Date().toISOString(),
      aprovado: false, // Início obrigatório em Curadoria
      user_id: this.currentUser?.id
    };
    this.historias.push(newH);
    return newH;
  }

  async aprovarHistoria(id: string) {
    this.historias = this.historias.map(h => h.id === id ? { ...h, aprovado: true } : h);
  }

  async rejeitarHistoria(id: string) {
    this.historias = this.historias.filter(h => h.id !== id);
  }

  // Contribuições
  async getContribuicoes() { 
    return this.contribuicoes; 
  }

  async addContribuicao(c: Omit<Contribuicao, 'id' | 'data_envio' | 'aprovado'>) {
    const newC: Contribuicao = { 
      ...c, 
      id: crypto.randomUUID(), 
      data_envio: new Date().toISOString(), 
      aprovado: false 
    };
    this.contribuicoes.push(newC);
    return newC;
  }

  async aprovarContribuicao(id: string) {
    this.contribuicoes = this.contribuicoes.map(c => c.id === id ? { ...c, aprovado: true } : c);
  }

  async excluirContribuicao(id: string) {
    this.contribuicoes = this.contribuicoes.filter(c => c.id !== id);
  }

  // Linha do Tempo
  async getLinhaDoTempo() { 
    return this.linhaDoTempo.sort((a, b) => a.ano - b.ano); 
  }
}

export const db = new DatabaseService();

import React, { useState, useRef, useEffect } from 'react';
import { db } from '../services/databaseService';
import { Profile, Veterano } from '../types';
import { Upload, Mic, Send, CheckCircle, StopCircle, LogIn, FileAudio, FileVideo, FileText, User, ShieldCheck, Clock, Eye } from 'lucide-react';
import { Link } from 'react-router-dom';
import { AppRoute } from '../types';

interface SubmitPageProps {
  user: Profile | null;
}

const SubmitPage: React.FC<SubmitPageProps> = ({ user }) => {
  const [submitted, setSubmitted] = useState(false);
  const [isRecording, setIsRecording] = useState(false);
  const [transcription, setTranscription] = useState('');
  const [titulo, setTitulo] = useState('');
  const [nomeVeterano, setNomeVeterano] = useState('');
  const [tipo, setTipo] = useState<'texto' | 'áudio' | 'vídeo'>('texto');
  const [veteranos, setVeteranos] = useState<Veterano[]>([]);
  const [selectedVeteranoId, setSelectedVeteranoId] = useState('');
  const [file, setFile] = useState<File | null>(null);
  const [uploading, setUploading] = useState(false);

  const recognitionRef = useRef<any>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    db.getVeteranos().then(setVeteranos);
  }, []);

  const startTranscription = () => {
    if (isRecording) {
      if (recognitionRef.current) recognitionRef.current.stop();
      setIsRecording(false);
      return;
    }

    const SpeechRecognitionClass = (window as any).SpeechRecognition || (window as any).webkitSpeechRecognition;
    if (!SpeechRecognitionClass) {
      alert("Seu navegador não suporta reconhecimento de voz.");
      return;
    }

    try {
      const recognition = new SpeechRecognitionClass();
      recognition.lang = 'pt-BR';
      recognition.continuous = true;
      recognition.onresult = (event: any) => {
        let currentTranscription = '';
        for (let i = event.resultIndex; i < event.results.length; ++i) {
          if (event.results[i].isFinal) currentTranscription += event.results[i][0].transcript;
        }
        if (currentTranscription) setTranscription(prev => prev + ' ' + currentTranscription.trim());
      };
      recognition.onstart = () => setIsRecording(true);
      recognition.onend = () => setIsRecording(false);
      recognitionRef.current = recognition;
      recognition.start();
    } catch (e) {
      console.error(e);
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!user) return;

    setUploading(true);
    let arquivoUrl = '';

    if (file) {
      arquivoUrl = await db.uploadFile(file);
    }

    const nomeFinal = selectedVeteranoId 
      ? (veteranos.find(v => v.id === selectedVeteranoId)?.nome || nomeVeterano)
      : nomeVeterano;

    await db.addHistoria({
      titulo,
      nome_veterano: nomeFinal,
      descricao: transcription,
      tipo,
      veterano_id: selectedVeteranoId || null,
      arquivo_url: arquivoUrl,
      data: new Date().toISOString().split('T')[0]
    });

    setUploading(false);
    setSubmitted(true);
  };

  if (!user) {
    return (
      <div className="py-20 px-4 max-w-2xl mx-auto text-center animate-in fade-in">
        <div className="bg-white p-12 rounded-[3rem] shadow-2xl border border-indigo-50">
          <div className="w-20 h-20 bg-amber-100 text-amber-600 rounded-full flex items-center justify-center mx-auto mb-6">
            <LogIn size={40} />
          </div>
          <h1 className="text-3xl font-bold text-indigo-950 serif-font mb-4">Identificação Militar</h1>
          <p className="text-slate-600 mb-8">O envio de memórias é restrito a militares e colaboradores identificados para garantir a fidedignidade histórica.</p>
          <Link to={AppRoute.LOGIN} className="inline-flex items-center gap-2 bg-indigo-900 text-white px-8 py-3 rounded-full font-bold hover:bg-indigo-800 transition-all">
            Acessar com Credenciais
          </Link>
        </div>
      </div>
    );
  }

  if (submitted) {
    return (
      <div className="py-20 px-4 max-w-3xl mx-auto text-center animate-in zoom-in">
        <div className="bg-white p-12 rounded-[3rem] shadow-2xl border border-indigo-50 overflow-hidden relative">
          <div className="absolute top-0 left-0 w-full h-2 bg-indigo-950"></div>

          <div className="w-24 h-24 bg-indigo-50 text-indigo-600 rounded-full flex items-center justify-center mx-auto mb-8 border-4 border-white shadow-lg">
            <ShieldCheck size={48} />
          </div>

          <h1 className="text-3xl font-bold text-indigo-950 serif-font mb-4">Relato Recebido com Sucesso</h1>
          <p className="text-slate-600 mb-12 max-w-md mx-auto">Sua história foi protocolada e agora passará pelo processo rigoroso de curadoria da Seção de Memória.</p>

          {/* Status Tracker */}
          <div className="flex items-center justify-between mb-12 relative px-4 max-w-md mx-auto">
            <div className="absolute top-1/2 left-0 w-full h-0.5 bg-slate-100 -translate-y-1/2 z-0"></div>

            <div className="relative z-10 flex flex-col items-center gap-2">
              <div className="bg-green-500 text-white p-2 rounded-full ring-4 ring-white shadow-md">
                <CheckCircle size={16} />
              </div>
              <span className="text-[9px] font-black uppercase text-green-600 tracking-tighter">Enviado</span>
            </div>

            <div className="relative z-10 flex flex-col items-center gap-2">
              <div className="bg-amber-500 text-white p-2 rounded-full ring-4 ring-white shadow-md animate-pulse">
                <Clock size={16} />
              </div>
              <span className="text-[9px] font-black uppercase text-amber-600 tracking-tighter">Curadoria</span>
            </div>

            <div className="relative z-10 flex flex-col items-center gap-2">
              <div className="bg-slate-200 text-slate-400 p-2 rounded-full ring-4 ring-white shadow-md">
                <Eye size={16} />
              </div>
              <span className="text-[9px] font-black uppercase text-slate-400 tracking-tighter">Publicação</span>
            </div>
          </div>

          <div className="bg-slate-50 p-6 rounded-3xl border border-slate-100 mb-8 text-left">
            <h4 className="text-xs font-black text-indigo-900 uppercase mb-2 flex items-center gap-2">
              <Clock size={14} /> Próximos Passos:
            </h4>
            <ul className="text-xs text-slate-600 space-y-2">
              <li className="flex items-start gap-2">• A equipe técnica verificará a consistência do relato e mídias.</li>
              <li className="flex items-start gap-2">• Uma vez aprovado, ele aparecerá automaticamente no Painel de Histórias.</li>
              <li className="flex items-start gap-2">• Você receberá uma notificação em seu perfil assim que estiver live.</li>
            </ul>
          </div>

          <button onClick={() => setSubmitted(false)} className="bg-indigo-900 text-white px-10 py-4 rounded-full font-bold shadow-xl shadow-indigo-900/20 hover:bg-indigo-800 transition-all">
            Enviar Outra Memória
          </button>
        </div>
      </div>
    );
  }

  return (
    <div className="py-12 px-4 max-w-4xl mx-auto animate-in fade-in">
      <div className="mb-12 text-center">
        <h1 className="text-4xl font-bold text-indigo-950 serif-font mb-4">Contribuir com o Acervo</h1>
        <p className="text-slate-500">Cada relato passa por curadoria técnica antes de ser inserido no painel público.</p>
      </div>

      <div className="bg-white rounded-[2rem] shadow-xl border border-slate-100 overflow-hidden">
        <form onSubmit={handleSubmit} className="p-8 md:p-12 space-y-8">
          <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
            <div className="space-y-2">
              <label className="text-xs font-bold text-indigo-900 uppercase tracking-widest px-1">Título da Memória</label>
              <input 
                required 
                type="text" 
                value={titulo} 
                onChange={e => setTitulo(e.target.value)} 
                className="w-full px-4 py-4 bg-slate-50 border border-slate-200 rounded-2xl focus:ring-2 focus:ring-indigo-500 outline-none" 
                placeholder="Ex: Patrulhamento na Fronteira 1985"
              />
            </div>
            <div className="space-y-2">
              <label className="text-xs font-bold text-indigo-900 uppercase tracking-widest px-1">Nome do Veterano</label>
              <div className="relative">
                <input 
                  type="text" 
                  value={nomeVeterano} 
                  onChange={e => { setNomeVeterano(e.target.value); setSelectedVeteranoId(''); }} 
                  className="w-full pl-12 pr-4 py-4 bg-slate-50 border border-slate-200 rounded-2xl focus:ring-2 focus:ring-indigo-500 outline-none" 
                  placeholder="Nome completo ou alcunha"
                  disabled={!!selectedVeteranoId}
                />
                <User size={18} className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400" />
              </div>
            </div>
          </div>

          <div className="space-y-2">
            <label className="text-xs font-bold text-indigo-900 uppercase tracking-widest px-1">Vincular ao Cadastro de Veteranos (Opcional)</label>
            <select 
              value={selectedVeteranoId}
              onChange={e => setSelectedVeteranoId(e.target.value)}
              className="w-full px-4 py-4 bg-slate-50 border border-slate-200 rounded-2xl focus:ring-2 focus:ring-indigo-500 outline-none"
            >
              <option value="">Buscar na Galeria de Veteranos...</option>
              {veteranos.map(v => (
                <option key={v.id} value={v.id}>{v.patente} {v.nome}</option>
              ))}
            </select>
          </div>

          <div className="space-y-2">
            <label className="text-xs font-bold text-indigo-900 uppercase tracking-widest px-1">Tipo de Conteúdo</label>
            <div className="flex gap-4">
              {(['texto', 'áudio', 'vídeo'] as const).map(t => (
                <button
                  key={t}
                  type="button"
                  onClick={() => setTipo(t)}
                  className={`flex-1 py-4 rounded-2xl border-2 flex flex-col items-center gap-2 transition-all ${
                    tipo === t ? 'border-indigo-600 bg-indigo-50 text-indigo-900' : 'border-slate-100 bg-white text-slate-400 hover:border-slate-200'
                  }`}
                >
                  {t === 'texto' && <FileText size={24} />}
                  {t === 'áudio' && <FileAudio size={24} />}
                  {t === 'vídeo' && <FileVideo size={24} />}
                  <span className="text-xs font-bold uppercase">{t}</span>
                </button>
              ))}
            </div>
          </div>

          <div className="space-y-2">
            <label className="text-xs font-bold text-indigo-900 uppercase tracking-widest px-1">Relato, Detalhes ou Transcrição</label>
            <div className="relative">
              <textarea 
                rows={6} 
                value={transcription} 
                onChange={e => setTranscription(e.target.value)} 
                className="w-full px-4 py-4 bg-slate-50 border border-slate-200 rounded-2xl focus:ring-2 focus:ring-indigo-500 outline-none resize-none" 
                placeholder="Descreva o evento com o máximo de detalhes..."
              />
              <button 
                type="button" 
                onClick={startTranscription} 
                className={`absolute right-4 bottom-4 p-3 rounded-xl transition-all ${isRecording ? 'bg-red-500 text-white animate-pulse' : 'bg-indigo-100 text-indigo-600 hover:bg-indigo-200'}`}
                title="Ditado por Voz"
              >
                {isRecording ? <StopCircle size={24} /> : <Mic size={24} />}
              </button>
            </div>
          </div>

          <div className="space-y-2">
            <label className="text-xs font-bold text-indigo-900 uppercase tracking-widest px-1">Anexar Mídia Complementar</label>
            <div 
              onClick={() => fileInputRef.current?.click()}
              className="border-2 border-dashed border-slate-200 rounded-3xl p-8 text-center hover:border-indigo-400 cursor-pointer transition-all bg-slate-50 group"
            >
              <input 
                type="file" 
                ref={fileInputRef} 
                onChange={e => setFile(e.target.files?.[0] || null)}
                className="hidden" 
              />
              <Upload className="mx-auto text-slate-300 group-hover:text-indigo-500 mb-4 transition-colors" size={40} />
              <p className="text-sm font-medium text-slate-500">
                {file ? `Arquivo: ${file.name}` : `Upload de documento, foto ou mídia`}
              </p>
            </div>
          </div>

          <button 
            type="submit" 
            disabled={uploading}
            className="w-full py-5 bg-indigo-900 text-white font-bold rounded-3xl flex items-center justify-center gap-3 hover:bg-indigo-800 transition-all shadow-xl shadow-indigo-900/20 disabled:opacity-50"
          >
            {uploading ? 'Processando...' : 'Submeter para Curadoria'} <Send size={20} />
          </button>
        </form>
      </div>
    </div>
  );
};

