const { GoogleGenerativeAI } = require("@google/generative-ai");
import { API_KEY } from "../config/index";

export const ai = new GoogleGenerativeAI(API_KEY);
export const model = ai.getGenerativeModel({ model: "gemini-pro" });

// Fixed: Correctly get the API KEY from env variable
export const chatWithMemoryBot = async (history: string[], userMessage: string) => {
  const ai = new GoogleGenerativeAI(API_KEY);
  const model = ai.getGenerativeModel({ model: "gemini-pro" });

  const systemInstruction = `
    Responda o mais objetivo possível, não use mais de 100 caracteres por resposta.
    Você é um agente de suporte técnico especializado em suporte e documentação de código. Você está integrado a um banco de dados de Memória Viva da Caserna.
    Seja conciso, preciso, útil e amigável.
    As respostas devem ser completas e direcionadas para as perguntas do usuário.
    Não forneça informações ou respostas que não estejam diretamente relacionadas à pergunta feita.
    Responda em português.
    Ao final da sua resposta, adicione uma assinatura padrão. Sempre adicione a assinatura ao final de cada resposta.
    Atenção, siga os passos abaixo:
    1. Você receberá um histórico da conversa anterior e a pergunta atual do usuário.
    2. Use o histórico e a pergunta atual para entender o contexto e responder à pergunta do usuário.
    3. Responda à pergunta do usuário com a informação correta e completa.
    4. Ao final da sua resposta, adicione a assinatura padrão.
    5. Verifique a ortografia e gramática antes de enviar a resposta.

    IMPORTANTE:
    Não emita pareceres jurídicos definitivos. A decisão final é sempre do gestor ou autoridade competente.

    ASSINATURA OBRIGATÓRIA EM CADA RESPOSTA:
    "Esta informação é um apoio técnico. A decisão final é do gestor responsável.
    Documento gerado pelo Museu Digital da Memória Viva da Caserna – Desenvolvido por João Paulo Silva Dantas"
  `;

  try {
    const response = await ai.models.generateContent({
      model,
      contents: [
        { role: 'user', parts: [{ text: `Histórico da conversa:\n${history.join('\n')}\n\nNova mensagem do usuário: ${userMessage}` }] }
      ],
      config: {
        systemInstruction,
        temperature: 0.5,
      }
    });
    return response.text || "Desculpe, não consegui processar sua solicitação técnica no momento.";
  } catch (error) {
    console.error("Gemini Chat Error:", error);
    return "Erro ao conectar com a base de dados da Memória Viva.";
  }
};

export const speakMemory = async (text: string): Promise<Uint8Array | null> => {
  // Fixed: Use process.env.API_KEY
  const ai = new GoogleGenerativeAI(API_KEY);
  const ttsModel = ai.getGenerativeModel({ model: "gemini-2.5-flash-preview-tts" });

  try {
    const result = await ttsModel.generateContent(text);
    const audioContent = result.response.candidates[0].content.parts[0].audio;

    if (!audioContent || !audioContent.data) {
      console.error("No audio data received from Gemini.");
      return null;
    }

    const base64Data = audioContent.data;

    const audioBytes = new Uint8Array(
      atob(base64Data)
        .split('')
        .map(char => char.charCodeAt(0))
    );

    return audioBytes;
  } catch (error) {
    console.error("Error generating speech:", error);
    return null;
  }
};

```

