const GalleryPage: React.FC = () => {
  const [veteranos, setVeteranos] = useState<Veterano[]>([]);
  const [historias, setHistorias] = useState<{[key: string]: Historia[]}>({});
  const [filter, setFilter] = useState<string>('Todos');
  const [search, setSearch] = useState('');
  const [selectedVeteran, setSelectedVeteran] = useState<Veterano | null>(null);
  const [isSpeaking, setIsSpeaking] = useState(false);

  const [playingAudioId, setPlayingAudioId] = useState<string | null>(null);
  const audioRefs = useRef<{ [key: string]: HTMLAudioElement | null }>({});

  useEffect(() => {
    const loadData = async () => {
      const vs = await db.getVeteranos();
      setVeteranos(vs);

      const hMap: {[key: string]: Historia[]} = {};
      for (const v of vs) {
        const vHist = await db.getHistoriasByVeterano(v.id);
        hMap[v.id] = vHist;
      }
      setHistorias(hMap);
    };
    loadData();
  }, []);

  const categories = ['Todos', 'Guarda Territorial', 'Polícia Militar'];

  const filteredVeterans = veteranos.filter(v => {
    const matchesFilter = filter === 'Todos' || v.origem === filter;
    const searchTerm = search.toLowerCase();
    const matchesBasic = v.nome.toLowerCase().includes(searchTerm) || 
                         (v.patente || '').toLowerCase().includes(searchTerm);
    const vHistorias = historias[v.id] || [];
    const matchesHistorias = vHistorias.some(h => 
      h.titulo.toLowerCase().includes(searchTerm) || 
      (h.descricao || '').toLowerCase().includes(searchTerm)
    );
    return matchesFilter && (matchesBasic || matchesHistorias);
  });

  const handleSpeak = async (text: string) => {
    if (isSpeaking) return;
    setIsSpeaking(true);
    try {
      const audioData = await speakMemory(text);
      if (audioData) {
        const AudioContextClass = (window as any).AudioContext || (window as any).webkitAudioContext;
        const ctx = new AudioContextClass();
        const dataInt16 = new Int16Array(audioData.buffer, audioData.byteOffset, audioData.length / 2);
        const frameCount = dataInt16.length;
        const buffer = ctx.createBuffer(1, frameCount, 24000);
        const channelData = buffer.getChannelData(0);
        for (let i = 0; i < frameCount; i++) channelData[i] = dataInt16[i] / 32768.0;
        const source = ctx.createBufferSource();
        source.buffer = buffer;
        source.connect(ctx.destination);
        source.onended = () => { setIsSpeaking(false); ctx.close(); };
        source.start();
      } else { setIsSpeaking(false); }
    } catch (error) { console.error(error); setIsSpeaking(false); }
  };

  const toggleAudio = (historiaId: string) => {
    const audio = audioRefs.current[historiaId];
    if (!audio) return;
    if (playingAudioId === historiaId) {
      audio.pause();
      setPlayingAudioId(null);
    } else {
      if (playingAudioId && audioRefs.current[playingAudioId]) audioRefs.current[playingAudioId]?.pause();
      audio.play();
      setPlayingAudioId(historiaId);
    }
  };

  return (
    <div className="py-12 px-4 max-w-7xl mx-auto animate-in fade-in duration-500">
      <div className="mb-12">
        <h1 className="text-4xl font-bold text-indigo-950 serif-font mb-4">Galeria de Veteranos</h1>
        <p className="text-slate-600 max-w-2xl">Preservando os rostos e as vozes daqueles que serviram ao Território e ao Estado.</p>
      </div>

      <div className="flex flex-col md:flex-row gap-4 mb-10">
        <div className="relative flex-grow">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
          <input 
            type="text" 
            placeholder="Pesquisar por nome, patente ou história..."
            className="w-full pl-10 pr-4 py-3 bg-white border border-slate-200 rounded-xl focus:ring-2 focus:ring-indigo-500 outline-none shadow-sm transition-all"
            value={search}
            onChange={(e) => setSearch(e.target.value)}
          />
        </div>
        <div className="flex gap-2 overflow-x-auto pb-2 md:pb-0 no-scrollbar">
          {categories.map(cat => (
            <button
              key={cat}
              onClick={() => setFilter(cat)}
              className={`px-6 py-3 rounded-xl font-bold whitespace-nowrap transition-all ${
                filter === cat ? 'bg-indigo-900 text-white shadow-lg' : 'bg-white text-slate-600 border border-slate-200 hover:bg-slate-50'
              }`}
            >
              {cat}
            </button>
          ))}
        </div>
      </div>

      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-8">
        {filteredVeterans.map(v => {
          const vHistorias = historias[v.id] || [];
          const matchedStory = search && vHistorias.find(h => 
            h.titulo.toLowerCase().includes(search.toLowerCase()) || 
            (h.descricao || '').toLowerCase().includes(search.toLowerCase())
          );

          return (
            <div key={v.id} className="group bg-white rounded-[2.5rem] overflow-hidden shadow-md hover:shadow-2xl transition-all border border-slate-100 flex flex-col relative">
              <div className="relative h-72 overflow-hidden">
                <img src={v.foto_url || 'https://via.placeholder.com/400'} alt={v.nome} className="w-full h-full object-cover grayscale group-hover:grayscale-0 transition-all duration-700" />
                <div className="absolute top-6 right-6 bg-indigo-950/80 backdrop-blur-md text-white px-4 py-1.5 rounded-full text-[10px] font-black uppercase tracking-widest border border-white/20">{v.origem}</div>

                {matchedStory && (
                  <div className="absolute bottom-0 inset-x-0 bg-amber-500/90 text-indigo-950 p-3 text-[10px] font-black uppercase tracking-widest text-center flex items-center justify-center gap-2">
                    <History size={14}/> Match: {matchedStory.titulo}
                  </div>
                )}
              </div>

              <div className="p-8 flex-grow flex flex-col">
                <div className="flex justify-between items-start mb-2">
                  <span className="text-amber-600 font-black text-[10px] uppercase tracking-[0.2em]">{v.patente}</span>
                </div>
                <h3 className="text-2xl font-bold text-indigo-950 serif-font mb-4 leading-tight">{v.nome}</h3>
                <p className="text-slate-600 text-sm line-clamp-3 mb-6 leading-relaxed flex-grow italic">
                  "{v.bio}"
                </p>

                <div className="mt-auto space-y-3">
                  <button onClick={() => setSelectedVeteran(v)} className="w-full bg-indigo-900 text-white py-4 rounded-2xl font-bold hover:bg-indigo-800 transition-all flex items-center justify-center gap-2 group/btn">
                    Ver Acervo Completo <ChevronRight size={18} className="group-hover/btn:translate-x-1 transition-transform" />
                  </button>
                  <div className="flex gap-2">
                    <button onClick={() => handleSpeak(`${v.nome}. ${v.bio}`)} disabled={isSpeaking} className="flex-1 p-3 bg-slate-100 text-indigo-950 rounded-xl hover:bg-amber-500 transition-all flex items-center justify-center gap-2 text-xs font-bold uppercase tracking-widest">
