                  </button>
                  <div className="flex gap-2">
                    <button onClick={() => handleSpeak(`${v.nome}. ${v.bio}`)} disabled={isSpeaking} className="flex-1 p-3 bg-slate-100 text-indigo-950 rounded-xl hover:bg-amber-500 transition-all flex items-center justify-center gap-2 text-xs font-bold uppercase tracking-widest">
                      <Volume2 size={16} className={isSpeaking ? 'animate-pulse' : ''}/> Narrativa IA
                    </button>
                  </div>
                </div>
              </div>
            </div>
          );
        })}
      </div>

      {selectedVeteran && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-indigo-950/90 backdrop-blur-sm overflow-y-auto">
          <div className="bg-white w-full max-w-5xl rounded-[3rem] overflow-hidden shadow-2xl relative my-8 animate-in zoom-in duration-300">
            <button onClick={closeDetail} className="absolute top-8 right-8 p-3 bg-slate-100 hover:bg-red-500 hover:text-white rounded-full transition-all z-20 shadow-lg">
              <X size={24} />
            </button>
            <div className="flex flex-col lg:flex-row h-full">
              <div className="lg:w-2/5 relative min-h-[400px]">
                <img src={selectedVeteran.foto_url} alt={selectedVeteran.nome} className="w-full h-full object-cover" />
                <div className="absolute inset-0 bg-gradient-to-t from-indigo-950/80 via-transparent to-transparent"></div>
                <div className="absolute bottom-8 left-8 right-8 text-white">
                  <p className="text-amber-400 text-xs font-black uppercase tracking-[0.3em] mb-2">{selectedVeteran.patente}</p>
                  <h2 className="text-3xl font-bold serif-font leading-tight">{selectedVeteran.nome}</h2>
                </div>
              </div>

              <div className="lg:w-3/5 p-8 lg:p-12 overflow-y-auto max-h-[90vh] bg-slate-50/50">
                <div className="mb-12">
