              }`}
            >
              {cat}
            </button>
          ))}
        </div>
      </div>

      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-8">
        {filteredVeterans.map(v => {
          const vHistorias = historias[v.id] || [];
          const matchedStory = search && vHistorias.find(h => 
            h.titulo.toLowerCase().includes(search.toLowerCase()) || 
            (h.descricao || '').toLowerCase().includes(search.toLowerCase())
          );

          return (
            <div key={v.id} className="group bg-white rounded-[2.5rem] overflow-hidden shadow-md hover:shadow-2xl transition-all border border-slate-100 flex flex-col relative">
              <div className="relative h-72 overflow-hidden">
                <img src={v.foto_url || 'https://via.placeholder.com/400'} alt={v.nome} className="w-full h-full object-cover grayscale group-hover:grayscale-0 transition-all duration-700" />
                <div className="absolute top-6 right-6 bg-indigo-950/80 backdrop-blur-md text-white px-4 py-1.5 rounded-full text-[10px] font-black uppercase tracking-widest border border-white/20">{v.origem}</div>

                {matchedStory && (
                  <div className="absolute bottom-0 inset-x-0 bg-amber-500/90 text-indigo-950 p-3 text-[10px] font-black uppercase tracking-widest text-center flex items-center justify-center gap-2">
                    <History size={14}/> Match: {matchedStory.titulo}
                  </div>
                )}
              </div>

              <div className="p-8 flex-grow flex flex-col">
                <div className="flex justify-between items-start mb-2">
                  <span className="text-amber-600 font-black text-[10px] uppercase tracking-[0.2em]">{v.patente}</span>
                </div>
                <h3 className="text-2xl font-bold text-indigo-950 serif-font mb-4 leading-tight">{v.nome}</h3>
                <p className="text-slate-600 text-sm line-clamp-3 mb-6 leading-relaxed flex-grow italic">
                  "{v.bio}"
                </p>

                <div className="mt-auto space-y-3">
                  <button onClick={() => setSelectedVeteran(v)} className="w-full bg-indigo-900 text-white py-4 rounded-2xl font-bold hover:bg-indigo-800 transition-all flex items-center justify-center gap-2 group/btn">
                    Ver Acervo Completo <ChevronRight size={18} className="group-hover/btn:translate-x-1 transition-transform" />
                  </button>
                  <div className="flex gap-2">
                    <button onClick={() => handleSpeak(`${v.nome}. ${v.bio}`)} disabled={isSpeaking} className="flex-1 p-3 bg-slate-100 text-indigo-950 rounded-xl hover:bg-amber-500 transition-all flex items-center justify-center gap-2 text-xs font-bold uppercase tracking-widest">
                      <Volume2 size={16} className={isSpeaking ? 'animate-pulse' : ''}/> Narrativa IA
                    </button>
                  </div>
                </div>
              </div>
            </div>
          );
        })}
      </div>

      {selectedVeteran && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-indigo-950/90 backdrop-blur-sm overflow-y-auto">
          <div className="bg-white w-full max-w-5xl rounded-[3rem] overflow-hidden shadow-2xl relative my-8 animate-in zoom-in duration-300">
            <button onClick={closeDetail} className="absolute top-8 right-8 p-3 bg-slate-100 hover:bg-red-500 hover:text-white rounded-full transition-all z-20 shadow-lg">
              <X size={24} />
            </button>
            <div className="flex flex-col lg:flex-row h-full">
              <div className="lg:w-2/5 relative min-h-[400px]">
                <img src={selectedVeteran.foto_url} alt={selectedVeteran.nome} className="w-full h-full object-cover" />
                <div className="absolute inset-0 bg-gradient-to-t from-indigo-950/80 via-transparent to-transparent"></div>
                <div className="absolute bottom-8 left-8 right-8 text-white">
                  <p className="text-amber-400 text-xs font-black uppercase tracking-[0.3em] mb-2">{selectedVeteran.patente}</p>
                  <h2 className="text-3xl font-bold serif-font leading-tight">{selectedVeteran.nome}</h2>
                </div>
              </div>

              <div className="lg:w-3/5 p-8 lg:p-12 overflow-y-auto max-h-[90vh] bg-slate-50/50">
                <div className="mb-12">
                  <h4 className="text-[10px] font-black text-indigo-900 uppercase tracking-widest mb-6 flex items-center gap-2 border-b border-indigo-100 pb-2">
                    <Info size={14} className="text-amber-500" /> Biografia Institucional
                  </h4>
                  <p className="text-slate-700 leading-relaxed text-lg serif-font italic bg-white p-8 rounded-[2rem] border border-slate-100 shadow-sm">
                    "{selectedVeteran.bio}"
                  </p>
                </div>

                <h4 className="text-[10px] font-black text-indigo-900 uppercase tracking-widest mb-6 flex items-center gap-2 border-b border-indigo-100 pb-2">
                  <History size={14} className="text-amber-500" /> Registros de Memória ({historias[selectedVeteran.id]?.length || 0})
                </h4>

                <div className="grid grid-cols-1 gap-6">
                  {(historias[selectedVeteran.id] || []).map(h => (
                    <div 
                      key={h.id} 
                      id={`story-${h.id}`}
                      className={`bg-white p-6 rounded-[2rem] border transition-all flex flex-col gap-4 group relative ${
                        sharedStoryId === h.id ? 'border-amber-400 ring-2 ring-amber-400/20 shadow-xl' : 'border-slate-100 shadow-sm hover:shadow-md'
                      }`}
                    >
                      {sharedStoryId === h.id && (
                        <div className="absolute -top-3 left-6 bg-amber-500 text-indigo-950 text-[8px] font-black uppercase px-3 py-1 rounded-full shadow-lg">
                          Destaque do Compartilhamento
                        </div>
                      )}

                      <div className="flex items-center justify-between">
                        <div className="flex items-center gap-3">
                          <div className={`p-2.5 rounded-2xl ${
                            h.tipo === 'áudio' ? 'bg-blue-100 text-blue-600' : 
                            h.tipo === 'vídeo' ? 'bg-purple-100 text-purple-600' : 
                            'bg-amber-100 text-amber-600'
                          }`}>
                            {h.tipo === 'áudio' ? <Mic size={20} /> : 
                             h.tipo === 'vídeo' ? <Video size={20} /> : 
                             <FileText size={20} />}
                          </div>
                          <div>
                            <h5 className="font-bold text-indigo-950 text-base">{h.titulo}</h5>
                            <span className="text-[9px] font-black text-slate-400 uppercase tracking-tighter">{h.data}</span>
                          </div>
                        </div>

                        <div className="flex items-center gap-2">
                           <button 
                             onClick={() => handleShareStory(selectedVeteran.id, h.id)}
                             className={`flex items-center gap-2 px-3 py-1.5 rounded-xl text-[9px] font-black uppercase transition-all border ${
                               copyFeedback === h.id ? 'bg-green-600 border-green-600 text-white' : 'bg-slate-50 border-slate-200 text-slate-500 hover:bg-indigo-900 hover:text-white hover:border-indigo-900'
                             }`}
                           >
                             {copyFeedback === h.id ? <Check size={12}/> : <Share2 size={12}/>}
                             {copyFeedback === h.id ? 'Copiado!' : 'Compartilhar'}
                           </button>
                           <span className={`text-[8px] font-black px-3 py-1 rounded-full uppercase tracking-widest ${
                             h.tipo === 'áudio' ? 'bg-blue-600 text-white' : 
                             h.tipo === 'vídeo' ? 'bg-purple-600 text-white' : 
                             'bg-amber-600 text-white'
                           }`}>
                             {h.tipo}
                           </span>
                        </div>
                      </div>

                      <div className="relative">
                        <p className="text-sm text-slate-600 leading-relaxed line-clamp-3 group-hover:line-clamp-none transition-all duration-500">
                          {h.descricao}
                        </p>
                      </div>

                      {h.localizacao && (
                        <div className="flex items-center gap-2 text-[10px] text-amber-600 font-bold uppercase tracking-wider">
                          <MapPin size={12} /> {h.localizacao}
                        </div>
                      )}

                      {/* Conteúdo de Mídia */}
                      {h.arquivo_url && h.tipo === 'áudio' && (
                        <div className="p-3 bg-slate-50 rounded-2xl border border-slate-100 flex items-center gap-4">
                           <button 
                             onClick={() => toggleAudio(h.id)} 
                             className="p-3 bg-indigo-900 text-white rounded-full hover:bg-indigo-800 transition-all"
                           >
                             {playingAudioId === h.id ? <Pause size={16}/> : <Play size={16}/>}
                           </button>
                           <div className="flex-1">
                             <div className="h-1.5 w-full bg-slate-200 rounded-full overflow-hidden">
                               <div className={`h-full bg-indigo-600 transition-all ${playingAudioId === h.id ? 'w-1/2 animate-pulse' : 'w-0'}`}></div>
                             </div>
                             {/* Fix: Ref callback must return void to avoid TS errors in React 18+ */}
                             <audio ref={el => { audioRefs.current[h.id] = el; }} src={h.arquivo_url} onEnded={() => setPlayingAudioId(null)} className="hidden" />
                           </div>
                        </div>
                      )}

                      {h.arquivo_url && h.tipo === 'vídeo' && (
                        <div className="rounded-2xl overflow-hidden shadow-sm aspect-video bg-black relative">
                          <video controls src={h.arquivo_url} className="w-full h-full object-contain" />
                        </div>
                      )}

                      {h.localizacao && (h.tipo === 'texto' || h.tipo === 'vídeo') && (
                        <MiniStoryMap location={h.localizacao} />
                      )}
                    </div>
                  ))}

                  {(!historias[selectedVeteran.id] || historias[selectedVeteran.id].length === 0) && (
                    <div className="text-center py-12 bg-white rounded-[2rem] border border-dashed border-slate-200">
                      <History className="mx-auto text-slate-200 mb-4" size={48} />
                      <p className="text-slate-400 text-sm font-medium">Acervo textual e multimídia em fase de curadoria.</p>
                    </div>
                  )}
                </div>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

