import { 
  Upload, Mic, Send, CheckCircle, StopCircle, LogIn, 
  FileAudio, FileVideo, FileText, User, ShieldCheck, 
  Clock, Eye, Image as ImageIcon, X, File as FileIcon,
  ShieldAlert, CheckSquare, Square
} from 'lucide-react';
